css:
.tpl-boxed *{box-sizing:border-box;margin:0;padding:0;-webkit-print-color-adjust:exact;print-color-adjust:exact}
.tpl-boxed,.tpl-boxed{width:210mm;height:297mm}
.tpl-boxed{font-family:Poppins,sans-serif;color:#3B2278}
.tpl-boxed .page{position:relative;width:210mm;height:297mm;overflow:hidden;background:#FFFBF3;
 background-image:radial-gradient(circle at 0 0,#FFE6F1 0,transparent 30%),radial-gradient(circle at 100% 0,#FFF0CF 0,transparent 30%),radial-gradient(circle at 100% 100%,#E1F3F4 0,transparent 30%),radial-gradient(circle at 0 100%,#EBE1FA 0,transparent 30%)}
.tpl-boxed .o1{position:absolute;inset:5mm;background:#5A2A9B} .tpl-boxed .o2{position:absolute;inset:6.8mm;background:#FFFBF3}
.tpl-boxed .o2:after{content:"";position:absolute;inset:0;background:inherit}
.tpl-boxed .sq{position:absolute} .tpl-boxed .st{left:9.4mm;right:9.4mm;top:8.2mm;height:2.8mm;background:repeating-linear-gradient(90deg,#D3217B 0mm 2.8mm,transparent 2.8mm 3.4mm,#F28A1B 3.4mm 6.199999999999999mm,transparent 6.199999999999999mm 6.799999999999999mm,#E5A91A 6.8mm 9.6mm,transparent 9.6mm 10.2mm,#35A653 10.2mm 13.0mm,transparent 13.0mm 13.6mm,#0E9AA0 13.6mm 16.4mm,transparent 16.4mm 17.0mm,#2A6FD6 17.0mm 19.8mm,transparent 19.8mm 20.400000000000002mm,#5A2A9B 20.4mm 23.2mm,transparent 23.2mm 23.8mm)} .tpl-boxed .sb{left:9.4mm;right:9.4mm;bottom:8.2mm;height:2.8mm;background:repeating-linear-gradient(90deg,#D3217B 0mm 2.8mm,transparent 2.8mm 3.4mm,#F28A1B 3.4mm 6.199999999999999mm,transparent 6.199999999999999mm 6.799999999999999mm,#E5A91A 6.8mm 9.6mm,transparent 9.6mm 10.2mm,#35A653 10.2mm 13.0mm,transparent 13.0mm 13.6mm,#0E9AA0 13.6mm 16.4mm,transparent 16.4mm 17.0mm,#2A6FD6 17.0mm 19.8mm,transparent 19.8mm 20.400000000000002mm,#5A2A9B 20.4mm 23.2mm,transparent 23.2mm 23.8mm)}
.tpl-boxed .sl{top:9.4mm;bottom:9.4mm;left:8.2mm;width:2.8mm;background:repeating-linear-gradient(180deg,#D3217B 0mm 2.8mm,transparent 2.8mm 3.4mm,#F28A1B 3.4mm 6.199999999999999mm,transparent 6.199999999999999mm 6.799999999999999mm,#E5A91A 6.8mm 9.6mm,transparent 9.6mm 10.2mm,#35A653 10.2mm 13.0mm,transparent 13.0mm 13.6mm,#0E9AA0 13.6mm 16.4mm,transparent 16.4mm 17.0mm,#2A6FD6 17.0mm 19.8mm,transparent 19.8mm 20.400000000000002mm,#5A2A9B 20.4mm 23.2mm,transparent 23.2mm 23.8mm)} .tpl-boxed .sr{top:9.4mm;bottom:9.4mm;right:8.2mm;width:2.8mm;background:repeating-linear-gradient(180deg,#D3217B 0mm 2.8mm,transparent 2.8mm 3.4mm,#F28A1B 3.4mm 6.199999999999999mm,transparent 6.199999999999999mm 6.799999999999999mm,#E5A91A 6.8mm 9.6mm,transparent 9.6mm 10.2mm,#35A653 10.2mm 13.0mm,transparent 13.0mm 13.6mm,#0E9AA0 13.6mm 16.4mm,transparent 16.4mm 17.0mm,#2A6FD6 17.0mm 19.8mm,transparent 19.8mm 20.400000000000002mm,#5A2A9B 20.4mm 23.2mm,transparent 23.2mm 23.8mm)}
.tpl-boxed .i1{position:absolute;inset:13.4mm;border:1.1mm solid #5A2A9B} .tpl-boxed .i2{position:absolute;inset:15.4mm;border:.45mm solid #E5A91A}
.tpl-boxed .cn{position:absolute;width:10.6mm;height:10.6mm;background:#5A2A9B} .tpl-boxed .cn b{position:absolute;inset:1.4mm;background:#E5A91A} .tpl-boxed .cn b:after{content:"";position:absolute;inset:1.4mm;background:#D3217B}
.tpl-boxed .cn svg{position:absolute;left:3.3mm;top:3.3mm;width:4mm;height:4mm}
.tpl-boxed .col{position:absolute;left:21mm;right:21mm;top:19mm;bottom:19mm;display:flex;flex-direction:column;align-items:center}
.tpl-boxed .url{font:700 5.8pt Poppins;letter-spacing:.4em;color:#D3217B}
.tpl-boxed .dbl{position:relative;color:#fff;text-align:center}
.tpl-boxed .hp{margin-top:2mm;background:#D3217B;padding:2mm 10mm;font:700 8.4pt Poppins;letter-spacing:.14em;box-shadow:0 0 0 .5mm #5A2A9B,inset 0 0 0 .8mm #D3217B,inset 0 0 0 1.1mm #E5A91A}
.tpl-boxed .kick{margin-top:2.6mm;font:700 11pt Poppins;letter-spacing:.42em;color:#F28A1B;padding-left:.42em}
.tpl-boxed .tri{font:700 46pt/1.05 Lora,serif;letter-spacing:.07em;color:#5A2A9B;text-shadow:.7mm .7mm 0 #E5A91A}
.tpl-boxed .dv{margin-top:1mm;display:flex;align-items:center;gap:2mm} .tpl-boxed .dv i{display:block;width:50mm;height:.45mm;background:#E5A91A} .tpl-boxed .dv b{width:2.4mm;height:2.4mm;background:#D3217B;transform:rotate(45deg)}
.tpl-boxed .ded{margin-top:2.6mm;background:#0E9AA0;padding:2mm 9mm;font:700 8pt Poppins;letter-spacing:.14em;box-shadow:inset 0 0 0 .8mm #0E9AA0,inset 0 0 0 1.15mm #FFFBF3}
.tpl-boxed .pf{margin-top:4mm;position:relative;width:42mm;height:49mm;padding:1.8mm;background:#fff;box-shadow:0 0 0 1mm #E5A91A,0 0 0 1.5mm #fff,0 0 0 2mm #5A2A9B,3.6mm 3.6mm 0 1.5mm #D3217B,6.8mm 6.8mm 0 1.5mm #0E9AA0}
.tpl-boxed .ph{position:relative;width:100%;height:100%;overflow:hidden;background:#EFE7FB;display:flex;justify-content:center;align-items:flex-end} .tpl-boxed .ph svg{width:88%;height:88%}
.tpl-boxed .ph span{position:absolute;bottom:2.4mm;font:700 4.8pt Poppins;letter-spacing:.14em;color:#5A2A9B} .tpl-boxed .ph img.pimg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.tpl-boxed .nm{margin-top:10mm;background:#5A2A9B;padding:2.4mm 14mm;font:700 20pt Lora,serif;letter-spacing:.07em;box-shadow:0 0 0 .6mm #E5A91A,inset 0 0 0 .9mm #5A2A9B,inset 0 0 0 1.3mm #E5A91A;min-width:110mm}
.tpl-boxed .role{margin-top:2.2mm;background:#0E9AA0;color:#fff;padding:1.2mm 8mm;font:700 8.6pt Poppins;letter-spacing:.12em;box-shadow:inset 0 0 0 .5mm #0E9AA0,inset 0 0 0 .85mm #fff}
.tpl-boxed .tag{margin-top:2.4mm;font:700 8pt Poppins;letter-spacing:.24em;color:#F28A1B}
.tpl-boxed .hh{margin-top:2mm;font:italic 700 17pt Lora,serif;color:#D3217B;display:flex;align-items:center;gap:3mm} .tpl-boxed .hh i{display:block;width:28mm;height:.45mm;background:#0E9AA0}
.tpl-boxed .box{margin-top:1.4mm;width:162mm;background:#fff;padding:3.4mm 9mm 2.6mm;text-align:center;box-shadow:0 0 0 .7mm #D3217B,inset 0 0 0 1.1mm #fff,inset 0 0 0 1.5mm #E5A91A}
.tpl-boxed .box p{font:400 7.8pt/1.45 Lora,serif;margin-bottom:1.3mm} .tpl-boxed .box p.e{font:italic 700 9.4pt Lora,serif;color:#D3217B;margin:0}
.tpl-boxed .ft{margin-top:auto;display:flex;flex-direction:column;align-items:center}
.tpl-boxed .fl{font:700 7pt Poppins;letter-spacing:.16em;color:#0E9AA0} .tpl-boxed .tk{margin-top:.8mm;font:500 6pt Poppins;letter-spacing:.3em;color:#5A2A9B}
.tpl-boxed .cv{font:700 27pt/1.1 Lora,serif;letter-spacing:.07em} .tpl-boxed .cy{font:700 6.6pt Poppins;letter-spacing:.16em;color:#F28A1B}
.tpl-boxed .og{margin-top:1.4mm;font:700 5.6pt Poppins;letter-spacing:.35em;color:#D3217B}
.tpl-boxed .chips{display:flex;gap:1.6mm;margin-top:1mm} .tpl-boxed .chip{padding:.5mm;} .tpl-boxed .chip i{display:block;font:700 6.4pt Poppins;font-style:normal;color:#fff;padding:.8mm 3mm;box-shadow:inset 0 0 0 .5mm #fff}
.tpl-boxed .q{margin-top:1.4mm;font:italic 700 7.4pt Lora,serif;color:#5A2A9B}
